// Mock store for RRT Portal — всё хранится в localStorage браузера.
// Состав подтягивается из Discord Worker'а.

import { DEFAULT_USERS, RANK_HISTORY, QUESTIONNAIRE, GUIDES } from './data';

const LS = {
  users: 'rrt_users',
  session: 'rrt_session',
  ranks: 'rrt_ranks',
  progress: 'rrt_progress',
  submissions: 'rrt_submissions',
  codes: 'rrt_codes',
  links: 'rrt_user_links',
  rosterCache: 'rrt_roster_cache',
  requests: 'rrt_activation_requests',
};

// ---------- утилиты ----------
function readJSON(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    return JSON.parse(raw);
  } catch {
    return fallback;
  }
}
function writeJSON(key, value) {
  localStorage.setItem(key, JSON.stringify(value));
}
function code6() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let out = '';
  for (let i = 0; i < 6; i++) out += chars[Math.floor(Math.random() * chars.length)];
  return out;
}

// ---------- инициализация ----------
export function init() {
  if (!localStorage.getItem(LS.users)) writeJSON(LS.users, DEFAULT_USERS);
  if (!localStorage.getItem(LS.ranks)) writeJSON(LS.ranks, RANK_HISTORY);
  if (!localStorage.getItem(LS.progress)) writeJSON(LS.progress, {});
  if (!localStorage.getItem(LS.submissions)) writeJSON(LS.submissions, []);
  if (!localStorage.getItem(LS.codes)) writeJSON(LS.codes, []);
  if (!localStorage.getItem(LS.links)) writeJSON(LS.links, {});
  if (!localStorage.getItem(LS.requests)) writeJSON(LS.requests, []);
}

// ---------- пользователи (из localStorage) ----------
export function getUsers() {
  return readJSON(LS.users, DEFAULT_USERS);
}
export function getUserById(id) {
  return getUsers().find((u) => u.id === id) || null;
}
export function currentUser() {
  const sess = readJSON(LS.session, null);
  if (!sess || !sess.id) return null;
  return getUserById(sess.id);
}

export function login(id, password) {
  const users = getUsers();
  const user = users.find((u) => u.id === id);
  if (!user) throw new Error('Пользователь с таким Discord ID не найден');
  if (user.password !== password) throw new Error('Неверный пароль');
  writeJSON(LS.session, { id: user.id, at: Date.now() });
  return user;
}

export function logout() {
  localStorage.removeItem(LS.session);
}

// ---------- заявки на код активации ----------

// Создать заявку на код
export function requestActivation(userId) {
  const uid = (userId || '').trim();
  if (!uid) throw new Error('Введите Discord User ID');
  if (!/^\d{17,20}$/.test(uid)) throw new Error('Неверный формат Discord User ID');

  const users = getUsers();
  const existing = users.find((u) => u.id === uid);

  // Если уже активирован — отказать
  if (existing && existing.password && existing.password.length > 0) {
    throw new Error('Этот Discord ID уже активирован. Войдите через форму «Вход».');
  }

  const requests = readJSON(LS.requests, []);
  const alreadyPending = requests.find((r) => r.userId === uid && r.status === 'pending');
  if (alreadyPending) {
    throw new Error('Заявка уже отправлена. Дождитесь одобрения Штаба.');
  }

  // Найти ник в Discord, если он уже известен
  let nickname = existing?.nickname || '';
  if (!nickname) {
    // Пытаемся найти в roster-кэше
    const roster = readJSON(LS.rosterCache, {});
    const found = (roster.data || []).find((u) => u.id === uid);
    nickname = found?.nickname || found?.displayName || '';
  }

  requests.push({
    userId: uid,
    nickname: nickname || '',
    status: 'pending',
    createdAt: Date.now(),
  });
  writeJSON(LS.requests, requests);
  return true;
}

// Получить список заявок (для админки)
export function getActivationRequests() {
  return readJSON(LS.requests, []);
}

// Одобрить заявку → выдать код
export function approveActivation(userId) {
  const requests = readJSON(LS.requests, []);
  const idx = requests.findIndex((r) => r.userId === userId && r.status === 'pending');
  if (idx < 0) throw new Error('Заявка не найдена');

  const code = code6();
  requests[idx].status = 'approved';
  requests[idx].code = code;
  requests[idx].approvedAt = Date.now();
  writeJSON(LS.requests, requests);

  // Дублируем код в общий список кодов (для activate)
  const codes = readJSON(LS.codes, []);
  codes.push({ code, userId, used: false, issuedAt: Date.now() });
  writeJSON(LS.codes, codes);

  return code;
}

// Отклонить заявку
export function rejectActivation(userId) {
  const requests = readJSON(LS.requests, []);
  const idx = requests.findIndex((r) => r.userId === userId && r.status === 'pending');
  if (idx < 0) throw new Error('Заявка не найдена');
  requests[idx].status = 'rejected';
  requests[idx].rejectedAt = Date.now();
  writeJSON(LS.requests, requests);
}

// ---------- активация ----------

export function issueActivation(userId) {
  const users = getUsers();
  const user = users.find((u) => u.id === userId);
  if (!user) throw new Error('Пользователь с таким Discord ID не найден');

  if (user.password && user.password.length > 0) {
    throw new Error('Этот пользователь уже активирован');
  }

  const codes = readJSON(LS.codes, []);
  const existing = codes.find((x) => x.userId === userId && !x.used);
  if (existing) return existing.code;

  const code = code6();
  codes.push({ code, userId, used: false, issuedAt: Date.now() });
  writeJSON(LS.codes, codes);
  return code;
}

// Владелец проекта — может активироваться без кода (bootstrap)
const OWNER_ID = '228194169020088321';
const OWNER_BOOTSTRAP = 'OWNER-228194169020088321'; // bootstrap-код

export function activate(userId, code, newPassword) {
  const uid = (userId || '').trim();
  const users = getUsers();
  const idx = users.findIndex((u) => u.id === uid);

  // ═══════════ BOOTSTRAP ДЛЯ ВЛАДЕЛЬЦА ═══════════
  if (uid === OWNER_ID && code.trim() === OWNER_BOOTSTRAP) {
    if (idx >= 0) {
      users[idx].password = newPassword;
      users[idx].pending = false;
      users[idx].accessRole = 'staff';
      users[idx].level = 5;
      writeJSON(LS.users, users);
      writeJSON(LS.session, { id: users[idx].id, at: Date.now() });
      return users[idx];
    } else {
      // если владельца нет в DEFAULT_USERS — создаём
      const newUser = {
        id: OWNER_ID,
        password: newPassword,
        nickname: 'Leprekon',
        displayName: 'Leprekon',
        accessRole: 'staff',
        level: 5,
        joinedAt: new Date().toISOString().slice(0, 10),
        birthDate: '',
        discordUsername: 'leprekon',
        discordGlobalName: 'Leprekon',
        discordRoles: ['[RRT]', 'Штаб'],
        discordJoinedAt: '',
        discordBoostSince: '',
        discordPending: false,
        avatarUrl: '',
      };
      users.push(newUser);
      writeJSON(LS.users, users);
      writeJSON(LS.session, { id: newUser.id, at: Date.now() });
      return newUser;
    }
  }

  // ═══════════ ОБЫЧНАЯ АКТИВАЦИЯ ═══════════
  const existing = users.find((u) => u.id === uid);
  if (existing && existing.password && existing.password.length > 0) {
    throw new Error('Этот Discord ID уже активирован. Войдите через форму «Вход».');
  }

  if (idx < 0) throw new Error('Пользователь не найден');

  const codes = readJSON(LS.codes, []);
  const c = codes.find((x) => x.userId === uid && x.code === code && !x.used);
  if (!c) throw new Error('Неверный или использованный код активации');

  c.used = true;
  c.usedAt = Date.now();
  writeJSON(LS.codes, codes);

  users[idx].password = newPassword;
  users[idx].pending = false;
  writeJSON(LS.users, users);

  writeJSON(LS.session, { id: users[idx].id, at: Date.now() });
  return users[idx];
}

// ---------- заявки (опросник) ----------
export function addSubmission(user, values) {
  const subs = readJSON(LS.submissions, []);
  subs.push({
    submitted_at: Math.floor(Date.now() / 1000),
    nickname: user.nickname,
    user_id: user.id,
    title: QUESTIONNAIRE.title,
    values,
  });
  writeJSON(LS.submissions, subs);
}
export function getSubmissions() {
  return readJSON(LS.submissions, []);
}

// ---------- звания ----------
export function getRanks() {
  return readJSON(LS.ranks, RANK_HISTORY);
}
export function addRank(userId, oldRank, newRank, changedAt, reason) {
  const ranks = readJSON(LS.ranks, RANK_HISTORY);
  if (!ranks[userId]) ranks[userId] = [];
  ranks[userId].unshift({
    changed_at: changedAt,
    old_rank: oldRank,
    new_rank: newRank,
    reason,
  });
  writeJSON(LS.ranks, ranks);
}

// ---------- участники (админ) ----------
export function upsertMember(m) {
  const users = getUsers();
  const idx = users.findIndex((u) => u.id === m.id);
  if (idx >= 0) {
    users[idx] = { ...users[idx], ...m };
  } else {
    users.push({
      id: m.id,
      nickname: m.nickname,
      displayName: m.displayName || m.nickname,
      accessRole: m.accessRole || 'recruit',
      joinedAt: m.joinedAt || new Date().toISOString().slice(0, 10),
      birthDate: m.birthDate || '',
      password: '',
      discordUsername: '',
      discordGlobalName: '',
      discordRoles: [],
      discordJoinedAt: '',
      discordBoostSince: '',
      discordPending: true,
      avatarUrl: '',
    });
  }
  writeJSON(LS.users, users);
}

// ---------- руководства / прогресс ----------
export function getGuideProgress(userId, guideKey) {
  const all = readJSON(LS.progress, {});
  const u = all[userId] || {};
  return u[guideKey] || {};
}
export function setBlockProgress(userId, guideKey, blockId, patch) {
  const all = readJSON(LS.progress, {});
  if (!all[userId]) all[userId] = {};
  if (!all[userId][guideKey]) all[userId][guideKey] = {};
  const cur = all[userId][guideKey][blockId] || {};
  all[userId][guideKey][blockId] = { ...cur, ...patch };
  writeJSON(LS.progress, all);
}
export function resetBlockProgress(userId, guideKey, blockId) {
  const all = readJSON(LS.progress, {});
  if (all[userId]?.[guideKey]?.[blockId]) {
    all[userId][guideKey][blockId] = { wrong_count: 0, resets: 0, locked: false, completed: false };
    writeJSON(LS.progress, all);
  }
}

// ---------- личные ссылки ----------
export function getUserLinks(userId) {
  const all = readJSON(LS.links, {});
  return Array.isArray(all[userId]) ? all[userId] : [];
}
export function setUserLinks(userId, links) {
  const all = readJSON(LS.links, {});
  all[userId] = (links || []).slice(0, 5);
  writeJSON(LS.links, all);
  return all[userId];
}

// ---------- аватарка (fallback) ----------
export function getAvatarUrl(user) {
  if (!user) return '';
  if (user.avatarUrl && user.avatarUrl.trim()) return user.avatarUrl;
  const seed = encodeURIComponent(user.nickname || user.id || 'rrt');
  return `https://api.dicebear.com/7.x/bottts-neutral/svg?seed=${seed}&backgroundColor=6b7a37,8e2c20,c9a94a&radius=8`;
}

