export function roleKeyFromLevel(level) {
  switch (level) {
    case 5: return 'marshal';
    case 4: return 'captain';
    case 3: return 'senior_sergeant';
    case 2: return 'recruit';
    case 1: return 'ticket';
    default: return 'recruit';
  }
}

// Оставьте для совместимости
export function levelToRole(level) {
  switch (level) {
    case 5: return 'staff';
    case 4: return 'officer';
    case 3: return 'unit';
    case 2: return 'recruit';
    case 1: return 'ticket';
    default: return null;
  }
}

