import React, { useEffect, useState } from 'react';

const STATS_URL = 'https://gist.githubusercontent.com/rrt-portal/c5e4f699ef9f28eb57dff81649f9bac3/raw/rrt-stats.json';

export default function Stats({ nickname }) {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetch(STATS_URL)
      .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
      .then((data) => {
        if (cancelled) return;
        const s = data?.players?.[nickname];
        if (!s) { setError('Игрок не найден в статистике'); setStats(null); }
        else setStats(s);
      })
      .catch((e) => { if (cancelled) return; console.error(e); setError('Не удалось загрузить статистику'); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [nickname]);

  if (loading) return <div className="card"><h2>Статистика</h2><p className="muted">Загрузка...</p></div>;
  if (error) return <div className="card"><h2>Статистика</h2><div className="notice danger">{error}</div></div>;
  return (
    <div className="card">
      <h2>Статистика</h2>
      <p className="muted">Игрок: <b className="mono">{nickname}</b></p>
      <div className="grid" style={{ marginTop: 14 }}>
        <div className="card" style={{ padding: 16 }}><h3>Убийства</h3><div className="stat">{stats.kills}</div></div>
        <div className="card" style={{ padding: 16 }}><h3>Смерти</h3><div className="stat">{stats.deaths}</div></div>
        <div className="card" style={{ padding: 16 }}><h3>K/D</h3><div className="stat">{stats.kd}</div></div>
        <div className="card" style={{ padding: 16 }}><h3>Игр всего</h3><div className="stat">{stats.games_total}</div></div>
      </div>
    </div>
  );
}