import React, { useEffect, useState } from 'react';
import './App.css';
import Login from './components/Login';
import Portal from './components/Portal';
import { init, currentUser } from './mock/store';

function ensureFont() {
  if (document.getElementById('rrt-fonts')) return;
  const l = document.createElement('link');
  l.id = 'rrt-fonts';
  l.rel = 'stylesheet';
  l.href = 'https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600;700&family=Rajdhani:wght@400;500;600;700&display=swap';
  document.head.appendChild(l);
}

function App() {
  const [user, setUser] = useState(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    ensureFont();
    init();
    setUser(currentUser());
    setReady(true);
  }, []);

  if (!ready) return null;

  if (!user) return <Login onLogin={setUser} />;

  return <Portal user={user} onLogout={() => setUser(null)} onUserRefresh={() => setUser(currentUser())} />;
}

export default App;
